/**
 * TASK: Complete TimestampedNote, a subclass of the provided BaseNote that
 * adds a minute field. BaseNote is provided -- do not edit it.
 *
 * BaseNote already has equals, hashCode and toString written for its single
 * text field, and its equals uses getClass() so a note is never equal to an
 * object of a different class.
 *
 * TimestampedNote must EXTEND that behaviour rather than replace it:
 *   equals    -- true only when super.equals(other) is true AND the minutes
 *                match. Two notes with the same text but different minutes are
 *                different notes, and a TimestampedNote is never equal to a
 *                plain BaseNote.
 *   hashCode  -- combine the inherited hash with the minute, the usual way:
 *                31 * super.hashCode() + minute. Notes that differ only by
 *                minute must produce different hash codes.
 *   toString  -- "TimestampedNote(text@minute)", e.g.
 *                "TimestampedNote(buy milk@90)".
 *
 * Getting these three right is what lets a HashSet spot real duplicates.
 */
class BaseNote {
    private final String text;

    public BaseNote(String text) {
        this.text = text;
    }

    public String getText() {
        return text;
    }

    @Override
    public boolean equals(Object other) {
        if (this == other) {
            return true;
        }
        if (other == null || getClass() != other.getClass()) {
            return false;
        }
        BaseNote note = (BaseNote) other;
        return text.equals(note.text);
    }

    @Override
    public int hashCode() {
        return text.hashCode();
    }

    @Override
    public String toString() {
        return "BaseNote(" + text + ")";
    }
}

public class TimestampedNote extends BaseNote {

    private final int minute;

    public TimestampedNote(String text, int minute) {
        // TODO: hand the text to the superclass, then store the minute
        super("");
        this.minute = minute;
    }

    public int getMinute() {
        return minute;
    }

    @Override
    public boolean equals(Object other) {
        // TODO: let the superclass check the class and the text first
        return false;
    }

    @Override
    public int hashCode() {
        // TODO: 31 * super.hashCode() + minute
        return 0;
    }

    @Override
    public String toString() {
        // TODO: "TimestampedNote(text@minute)"
        return "";
    }
}

