public class TimestampedNoteTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object safe(java.util.function.Supplier<Object> body) {
        try {
            return body.get();
        } catch (Throwable t) {
            return "<threw " + t.getClass().getSimpleName() + ">";
        }
    }

    public static void main(String[] args) {
        TimestampedNote a = new TimestampedNote("buy milk", 90);
        TimestampedNote b = new TimestampedNote("buy milk", 90);
        TimestampedNote c = new TimestampedNote("buy milk", 15);
        TimestampedNote d = new TimestampedNote("call mum", 90);

        check("text reached the superclass", "buy milk", safe(a::getText));
        check("same text and minute are equal", Boolean.TRUE, safe(() -> a.equals(b)));
        check("equal notes share a hash code", Boolean.TRUE,
                safe(() -> a.hashCode() == b.hashCode()));
        check("different minute is not equal", Boolean.FALSE, safe(() -> a.equals(c)));
        check("different minute gives a different hash code", Boolean.TRUE,
                safe(() -> a.hashCode() != c.hashCode()));
        check("different text is not equal", Boolean.FALSE, safe(() -> a.equals(d)));
        check("a note equals itself", Boolean.TRUE, safe(() -> a.equals(a)));
        check("null is not equal", Boolean.FALSE, safe(() -> a.equals(null)));
        check("a plain BaseNote is not equal", Boolean.FALSE,
                safe(() -> a.equals(new BaseNote("buy milk"))));
        check("and the comparison is refused in both directions", Boolean.FALSE,
                safe(() -> new BaseNote("buy milk").equals(a)));
        check("toString", "TimestampedNote(buy milk@90)", safe(a::toString));
        check("a HashSet folds the duplicate together", 3,
                safe(() -> {
                    java.util.Set<BaseNote> set = new java.util.HashSet<>();
                    set.add(a);
                    set.add(b);
                    set.add(c);
                    set.add(d);
                    return set.size();
                }));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

