public class TimestampedNote extends BaseNote {

    private final int minute;

    public TimestampedNote(String text, int minute) {
        super(text);
        this.minute = minute;
    }

    public int getMinute() {
        return minute;
    }

    @Override
    public boolean equals(Object other) {
        if (!super.equals(other)) {
            return false;
        }
        TimestampedNote note = (TimestampedNote) other;
        return minute == note.minute;
    }

    @Override
    public int hashCode() {
        return 31 * super.hashCode() + minute;
    }

    @Override
